<?php
class SubscriptionController {
 public function index():void {Auth::require();$plans=db_all('SELECT * FROM plans WHERE active=1 ORDER BY price_month');$current=db_one('SELECT s.*,p.name plan_name,p.price_month,p.price_year FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.company_id=? ORDER BY s.id DESC LIMIT 1',[company_id()]);$payments=db_all('SELECT * FROM payment_transactions WHERE company_id=? ORDER BY id DESC LIMIT 20',[company_id()]);View::render('business/subscription',compact('plans','current','payments'));}
 public function request():void {Auth::require();verify_csrf();$plan=db_one('SELECT * FROM plans WHERE id=? AND active=1',[(int)($_POST['plan_id']??0)]);if(!$plan){flash('error','Offre inconnue.');redirect('/subscription');}$cycle=$_POST['cycle']==='yearly'?'yearly':'monthly';$amount=(float)$plan[$cycle==='yearly'?'price_year':'price_month'];$pdo=Database::p();$pdo->beginTransaction();try{$sid=db_exec('INSERT INTO subscriptions(company_id,plan_id,status,billing_cycle,starts_at,created_at) VALUES(?,?,"pending",?,NOW(),NOW())',[company_id(),$plan['id'],$cycle]);$ref='FBPAY-'.strtoupper(bin2hex(random_bytes(5)));db_exec('INSERT INTO payment_transactions(company_id,subscription_id,provider,provider_reference,amount,currency,status,metadata,created_at) VALUES(?,?,"manual",?,?,"XOF","pending",?,NOW())',[company_id(),$sid,$ref,$amount,json_encode(['plan'=>$plan['code'],'cycle'=>$cycle])]);$pdo->commit();Security::audit('subscription.requested','subscription',$sid,['reference'=>$ref]);flash('success','Demande enregistrée. Le paiement sera activé après confirmation par Coteamdev. Référence : '.$ref);}catch(Throwable $e){$pdo->rollBack();flash('error','Impossible de créer la demande.');}redirect('/subscription');}
}
